def transform(grid):
    rows = len(grid)
    cols = len(grid[0])

    bg = grid[0][0]
    center_r = rows // 2
    center_c = cols // 2
    cross_color = grid[center_r][center_c]

    out_rows = rows - 1
    out_cols = cols - 1

    output = [[bg for _ in range(out_cols)] for _ in range(out_rows)]

    # Pattern in center - 6x4 region
    pattern_top = out_rows // 2 - 2
    pattern_left = out_cols // 2 - 2

    for r in range(out_rows):
        for c in range(out_cols):
            if pattern_top <= r <= pattern_top + 5:
                if pattern_left <= c <= pattern_left + 3:
                    row_offset = r - pattern_top
                    col_offset = c - pattern_left
                    if row_offset < 2 and (col_offset == 0 or col_offset == 3):
                        output[r][c] = cross_color
                    elif row_offset >= 2 and row_offset <= 3:
                        output[r][c] = cross_color
                    elif row_offset > 3 and col_offset == 0 or col_offset == 3:
                        output[r][c] = cross_color

    return output
